// Node: "Config" — edit these values after import. Secrets live in n8n credentials, not here.
return [{
  json: {
    siteBase: 'https://www.cybermfukoni.co.ke',
    sitemapUrl: 'https://www.cybermfukoni.co.ke/sitemap.xml',
    ogImageEndpoint: 'https://www.cybermfukoni.co.ke/api/og',   // must return image/jpeg for Instagram
    blogWebhookUrl: 'https://www.cybermfukoni.co.ke/api/engine/posts',
    facebookPageId: 'REPLACE_PAGE_ID',
    instagramUserId: 'REPLACE_IG_USER_ID',
    metaGraphVersion: 'v23.0',
    telegramReviewerChatId: 'REPLACE_CHAT_ID',
    gscProperty: 'sc-domain:cybermfukoni.co.ke',
    channels: ['blog', 'facebook', 'instagram', 'x'],   // remove one to skip it (do not disable nodes)
    llmModel: 'claude-sonnet-5-5',
    maxAttempts: 3,          // 1 generation + 2 compliance-driven revisions
    cooldownDays: 30,
    // Verified windows only. MM-DD inclusive; may wrap the year end.
    seasonal: [
      { name: 'KRA individual income tax returns (deadline 30 June)', start: '05-15', end: '06-30',
        tokens: ['kra', 'returns', 'tax', 'itax', 'nil', 'p9'], boost: 1 },
    ],
  },
}];

// Node: "Select Target" — rank services from the live sitemap (mirrors cm_agent/demand.py).
// score = 0.45*GSC striking-distance + 0.30*seasonal + 0.25*coverage gap; cooldown via static data.
const cfg = $('Config').first().json;
const xml = String($('Fetch Sitemap').first().json.data || '');
let gscRows = [];
try { gscRows = $('GSC Page Stats').first().json.rows || []; } catch (e) { gscRows = []; }

const host = new URL(cfg.siteBase).host;
const SERVICE = /^\/government-agencies\/([^/]+)\/service\/([^/]+)\/?$/;
const BLOG = /^\/blog\/((?!category\/)[^/]+)\/?$/;
const services = [];
const blogSlugs = [];
for (const m of xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)) {
  let u;
  try { u = new URL(m[1]); } catch (e) { continue; }
  if (u.host !== host) continue;
  const s = u.pathname.match(SERVICE);
  if (s) { services.push({ url: u.href, agency: s[1], slug: s[2] }); continue; }
  const b = u.pathname.match(BLOG);
  if (b) blogSlugs.push(b[1]);
}
if (!services.length) throw new Error('Sitemap returned no service URLs');

const tokens = (slug) => new Set(slug.toLowerCase().split(/[-_]/).filter((t) => t.length > 2));
const jaccard = (a, b) => {
  const inter = [...a].filter((x) => b.has(x)).length;
  const union = new Set([...a, ...b]).size;
  return union ? inter / union : 0;
};

// Today in EAT (Africa/Nairobi, UTC+3, no DST).
const nowEat = new Date(Date.now() + 3 * 3600 * 1000);
const mmdd = (d) => [d.getUTCMonth() + 1, d.getUTCDate()];
const [tm, td] = mmdd(nowEat);
const inWindow = (start, end) => {
  const v = tm * 100 + td;
  const [sm, sd] = start.split('-').map(Number);
  const [em, ed] = end.split('-').map(Number);
  const s = sm * 100 + sd, e = em * 100 + ed;
  return s <= e ? v >= s && v <= e : v >= s || v <= e;
};

const gsc = {};
for (const r of gscRows) gsc[r.keys[0]] = r;
const gscRaw = (r) => (r ? r.impressions * (r.position >= 4 && r.position <= 20 ? 1 : 0.25) : 0);

const store = $getWorkflowStaticData('global');
store.history = store.history || {};
const cutoff = Date.now() - cfg.cooldownDays * 86400 * 1000;

const rows = services.filter((s) => !(store.history[s.slug] && Date.parse(store.history[s.slug]) >= cutoff));
const maxG = Math.max(0, ...rows.map((s) => gscRaw(gsc[s.url]))) || 1;
const blogTok = blogSlugs.map(tokens);

const ranked = rows.map((s) => {
  const t = tokens(s.slug);
  const g = gscRaw(gsc[s.url]) / maxG;
  let seasonal = 0;
  const reasons = [];
  for (const ev of cfg.seasonal) {
    if (inWindow(ev.start, ev.end) && ev.tokens.some((x) => t.has(x)) && ev.boost > seasonal) {
      seasonal = Math.min(ev.boost, 1);
      reasons.push(`seasonal: ${ev.name}`);
    }
  }
  const gap = t.size ? 1 - Math.max(0, ...blogTok.map((b) => jaccard(t, b))) : 0;
  if (g > 0) {
    const r = gsc[s.url];
    reasons.push(`gsc: ${Math.round(r.impressions)} impr, pos ${r.position.toFixed(1)}, ctr ${(r.ctr * 100).toFixed(2)}%`);
  }
  if (gap >= 0.8) reasons.push('no matching blog post');
  return { ...s, score: +(0.45 * g + 0.3 * seasonal + 0.25 * gap).toFixed(4), reasons };
}).sort((a, b) => b.score - a.score || a.slug.localeCompare(b.slug));

if (!ranked.length) return [{ json: { noCandidate: true, reason: 'all services in cooldown' } }];
return [{ json: { noCandidate: false, target: ranked[0], runnersUp: ranked.slice(1, 5), blogSlugs } }];

// Node: "Extract Facts" — deterministic facts from the target page (mirrors cm_agent/catalog.py).
// Price/turnaround come ONLY from the text between the H1 and the next h1-h4 heading,
// which keeps cross-sell prices (e.g. eCitizen setup) out.
const sel = $('Select Target').first().json;
const t = sel.target;
const html = String($('Fetch Service Page').first().json.data || '');

const decode = (s) => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&#x27;/g, "'").replace(/&nbsp;/g, ' ');
const text = (s) => decode(s.replace(/<!--[\s\S]*?-->/g, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

const h1m = html.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i);
const titleM = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const metaM = html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i);
let block = '';
if (h1m) {
  const after = html.slice(h1m.index + h1m[0].length);
  const stop = after.search(/<h[1-4]\b/i);
  block = text(stop >= 0 ? after.slice(0, stop) : after).slice(0, 600);
}
const amounts = [...block.matchAll(/\b(?:KES|Kshs?\.?)\s*([\d,]+(?:\.\d{2})?)/gi)]
  .map((m) => Math.round(parseFloat(m[1].replace(/,/g, ''))));
const days = [...block.matchAll(/\b(\d{1,3})\s*(?:working\s+)?days?\b/gi)].map((m) => parseInt(m[1], 10));

let documents = [];
const docH = html.match(/<h[2-4]\b[^>]*>[^<]*(?:Require|Document)[^<]*<\/h[2-4]>([\s\S]*?)<\/(?:ul|ol)>/i);
if (docH) documents = [...docH[1].matchAll(/<li\b[^>]*>([\s\S]*?)<\/li>/gi)].map((m) => text(m[1])).slice(0, 12);

let requestUrl = `https://app.cybermfukoni.co.ke/service-requests/create?agency=${t.agency}&service=${t.slug}`;
for (const m of html.matchAll(/href=["']([^"']*service-requests\/create[^"']*)["']/gi)) {
  const href = decode(m[1]);
  try { if (new URL(href).searchParams.get('service') === t.slug) { requestUrl = href; break; } } catch (e) { /* skip */ }
}

const priceAmbiguous = new Set(amounts).size > 1;
return [{
  json: {
    agency: t.agency,
    slug: t.slug,
    url: t.url,
    requestUrl,
    reasons: t.reasons,
    blogSlugs: sel.blogSlugs,
    h1: h1m ? text(h1m[1]) : '',
    title: titleM ? text(titleM[1]) : '',
    metaDescription: metaM ? decode(metaM[1]) : '',
    priceKes: amounts.length ? amounts[0] : null,
    priceAmbiguous,
    turnaroundDays: days.length ? days[0] : null,
    documents,
  },
}];

// Node: "Build LLM Request" — first pass from Extract Facts; later passes receive the
// compliance output (violations) through the revision loop.
const cfg = $('Config').first().json;
const f = $('Extract Facts').first().json;
const incoming = $input.first().json;
const feedback = Array.isArray(incoming.violations) ? incoming.violations : [];
const attempt = (incoming.attempt || 0) + 1;

const system = `You are the content strategist for Cyber Mfukoni, an independent private
consultancy in Kenya that helps citizens and businesses complete government processes
(eCitizen, KRA, NTSA, BRS, TSC, KUCCPS and others) for a service fee.
Audience: Kenyans on mobile, often first-time portal users. Voice: clear Kenyan English;
social posts may use light, natural Sheng/Swahili phrases.

HARD RULES (violations are rejected automatically):
1. Fees and turnaround: state ONLY the values in FACTS, written exactly as "KES <amount>" and
   "<n> days". If FACTS gives null, mention no amount and no number of days. No statutory fees.
2. Never imply affiliation with, approval by, or acting on behalf of any government body.
   Never use "official", "guarantee", "100% approval", "skip the queue".
3. Links: only the placeholders {{CTA}} (request form) and {{SERVICE_PAGE}} (service page).
   Never write raw URLs. Instagram caption: no links, say "link in bio".
4. Do not invent requirements; use FACTS.documents or refer readers to the service page.
5. Blog: step-by-step guide, H2/H3 only, >= 600 words, 3-6 FAQs.

OUTPUT: a single JSON object and nothing else, exactly this shape:
{"primary_keyword": str,
 "blog": {"title": str (<=60 chars), "slug": str (lowercase-hyphenated, unique),
          "meta_description": str (70-160 chars), "body_markdown": str (uses {{SERVICE_PAGE}} once,
          ends with a call to action linking {{CTA}}), "faqs": [{"question": str, "answer": str}] (3-6)},
 "facebook_post": str (80-180 words, ends with {{CTA}}),
 "x_post": str (<= 250 chars including {{CTA}}),
 "instagram_caption": str (<= 1500 chars),
 "instagram_hashtags": [str] (3-8, no # prefix),
 "tiktok": {"hook": str, "beats": [str] (3-6), "on_screen_text": [str] (3-6), "cta": str}}`;

const facts = {
  service_name: f.h1 || f.title,
  agency_slug: f.agency,
  fee_kes: f.priceAmbiguous ? null : f.priceKes,
  turnaround_days: f.turnaroundDays,
  documents: f.documents,
  page_summary: f.metaDescription,
  existing_blog_slugs_to_avoid: f.blogSlugs.slice(0, 200),
};
let user = `FACTS:\n${JSON.stringify(facts, null, 2)}\n\nWHY THIS SERVICE NOW:\n` +
  ((f.reasons || []).map((r) => `- ${r}`).join('\n') || '- rotation');
if (feedback.length) {
  user += '\n\nYOUR PREVIOUS DRAFT WAS REJECTED BY THE COMPLIANCE GATE. Fix every item and change ' +
    'nothing else unnecessarily:\n' + feedback.map((v) => `- [${v.channel}] ${v.rule}: ${v.detail}`).join('\n');
}

return [{
  json: {
    attempt,
    body: {
      model: cfg.llmModel,
      max_tokens: 8000,
      temperature: 0.4,
      system,
      messages: [{ role: 'user', content: user }],
    },
  },
}];

// Node: "Assemble + Compliance" — parse LLM JSON, insert tracked links, disclaimer, JSON-LD,
// then run the deterministic gate (mirrors cm_agent/assemble.py + compliance.py).
const cfg = $('Config').first().json;
const f = $('Extract Facts').first().json;
const attempt = $runIndex + 1;
const executionId = $execution.id;
const resp = $input.first().json;

const violations = [];
const V = (channel, rule, detail) => violations.push({ channel, rule, detail });

// ---------- parse + shape validation
let pack = null;
try {
  if (resp.error) throw new Error(`LLM HTTP error: ${JSON.stringify(resp.error).slice(0, 300)}`);
  const txt = (resp.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
  const s = txt.indexOf('{'), e = txt.lastIndexOf('}');
  if (s < 0 || e <= s) throw new Error('no JSON object in response');
  pack = JSON.parse(txt.slice(s, e + 1));
  const str = (v) => typeof v === 'string' && v.trim().length > 0;
  const arr = (v) => Array.isArray(v);
  const ok = pack && str(pack.primary_keyword) && pack.blog && str(pack.blog.title) && str(pack.blog.slug)
    && str(pack.blog.meta_description) && str(pack.blog.body_markdown) && arr(pack.blog.faqs)
    && pack.blog.faqs.every((q) => str(q.question) && str(q.answer))
    && str(pack.facebook_post) && str(pack.x_post) && str(pack.instagram_caption)
    && arr(pack.instagram_hashtags) && pack.tiktok && str(pack.tiktok.hook) && arr(pack.tiktok.beats)
    && arr(pack.tiktok.on_screen_text) && str(pack.tiktok.cta);
  if (!ok) throw new Error('JSON does not match the required shape');
} catch (err) {
  V('all', 'SCHEMA_INVALID', String(err.message || err));
  return [{ json: { passed: false, attempt, violations, maxAttempts: cfg.maxAttempts } }];
}

// ---------- assemble
const utm = (url, source, medium) => {
  const u = new URL(url);
  u.searchParams.set('utm_source', source);
  u.searchParams.set('utm_medium', medium);
  u.searchParams.set('utm_campaign', 'cm_engine');
  u.searchParams.set('utm_content', `n8n-${executionId}`);
  return u.toString();
};
const fill = (t, cta, page) => t.split('{{CTA}}').join(cta).split('{{SERVICE_PAGE}}').join(page);
const DISCLAIMER = '\n\n---\n\n*Cyber Mfukoni is an independent private consultancy. We are not affiliated '
  + 'with the Government of Kenya or any state agency. Every service listed here can also be accessed '
  + 'directly through the relevant government portal; our fee covers professional assistance in addition '
  + 'to any statutory charges.*';
const priceOk = f.priceKes !== null && !f.priceAmbiguous;

const serviceLd = {
  '@context': 'https://schema.org', '@type': 'Service', name: f.h1 || f.title, url: f.url,
  areaServed: { '@type': 'Country', name: 'Kenya' },
  provider: { '@type': 'Organization', name: 'Cyber Mfukoni', url: cfg.siteBase },
};
if (priceOk) serviceLd.offers = { '@type': 'Offer', price: String(f.priceKes), priceCurrency: 'KES', url: f.requestUrl };
const faqLd = {
  '@context': 'https://schema.org', '@type': 'FAQPage',
  mainEntity: pack.blog.faqs.map((q) => ({ '@type': 'Question', name: q.question,
    acceptedAnswer: { '@type': 'Answer', text: q.answer } })),
};
const hashtags = pack.instagram_hashtags.map((h) => '#' + String(h).replace(/^#/, '').replace(/\s+/g, '')).join(' ');
const content = {
  primary_keyword: pack.primary_keyword,
  blog: {
    title: pack.blog.title,
    slug: pack.blog.slug,
    canonical_url: `${cfg.siteBase}/blog/${pack.blog.slug}`,
    meta_description: pack.blog.meta_description,
    body_markdown: fill(pack.blog.body_markdown, utm(f.requestUrl, 'blog', 'owned'), utm(f.url, 'blog', 'owned')) + DISCLAIMER,
    faqs: pack.blog.faqs,
    jsonld: [serviceLd, faqLd],
    og_image: `${cfg.ogImageEndpoint}?title=${encodeURIComponent(pack.blog.title)}`,
  },
  facebook: {
    message: fill(pack.facebook_post, utm(f.requestUrl, 'facebook', 'social'), utm(f.url, 'facebook', 'social')),
    link: utm(f.requestUrl, 'facebook', 'social'),
  },
  x: { text: fill(pack.x_post, utm(f.requestUrl, 'x', 'social'), utm(f.url, 'x', 'social')) },
  instagram: {
    caption: `${fill(pack.instagram_caption, 'link in bio', 'link in bio')}\n\n${hashtags}`.trim(),
    image_url: `${cfg.ogImageEndpoint}?title=${encodeURIComponent(f.h1 || pack.blog.title)}`,
  },
  tiktok: pack.tiktok,
};

// ---------- compliance
const AMOUNT = /\b(?:KES|KSh|Kshs?)\.?\s*([\d,]+(?:\.\d{1,2})?)|\b([\d,]+)\s*(?:shillings|bob)\b/gi;
const DAYS = /\b(\d{1,3})\s*(?:working\s+|business\s+)?days?\b/gi;
const URLRX = /https?:\/\/[^\s)\]>"']+/gi;
const AG = '(?:kra|ntsa|ecitizen|e-citizen|government|gok|tsc|kuccps|helb|immigration|nrb|brs|sha|nssf|police|dci)';
const IMPERSONATION = [
  new RegExp(`\\bofficial\\s+${AG}\\b`, 'gi'),
  new RegExp(`\\b${AG}[- ](?:approved|accredited|certified|authori[sz]ed)\\b`, 'gi'),
  new RegExp(`\\b(?:approved|accredited|authori[sz]ed|licensed)\\s+(?:by|agents?\\s+of)\\s+(?:the\\s+)?${AG}\\b`, 'gi'),
  new RegExp(`\\bwe\\s+are\\s+(?:the\\s+)?${AG}\\b`, 'gi'),
  new RegExp(`\\bon\\s+behalf\\s+of\\s+(?:the\\s+)?${AG}\\b`, 'gi'),
  /\bguarantee(?:d|s)?\b/gi,
  /\b100\s*%\s*(?:approval|success|guaranteed)\b/gi,
  /\b(?:skip|jump|beat)\s+the\s+queue\b/gi,
];
const xWeighted = (t) => {
  const urls = t.match(URLRX) || [];
  let n = 23 * urls.length;
  for (const ch of t.replace(URLRX, '')) {
    const cp = ch.codePointAt(0);
    const light = cp <= 0x10ff || (cp >= 0x2000 && cp <= 0x200d) || (cp >= 0x2010 && cp <= 0x201f)
      || (cp >= 0x2032 && cp <= 0x2037);
    n += light ? 1 : 2;
  }
  return n;
};

const b = content.blog;
const texts = {
  blog: [b.title, b.meta_description, b.body_markdown, ...b.faqs.map((q) => `${q.question}\n${q.answer}`)].join('\n'),
  facebook: content.facebook.message,
  x: content.x.text,
  instagram: content.instagram.caption,
  tiktok: [content.tiktok.hook, ...content.tiktok.beats, ...content.tiktok.on_screen_text, content.tiktok.cta].join('\n'),
};
for (const [ch, t] of Object.entries(texts)) {
  for (const m of t.matchAll(AMOUNT)) {
    const amt = Math.round(parseFloat((m[1] || m[2]).replace(/,/g, '')));
    if (!(priceOk && amt === f.priceKes)) V(ch, 'FEE_MISMATCH', `'${m[0]}' not in catalog fee ${priceOk ? f.priceKes : 'none-allowed'}`);
  }
  for (const m of t.matchAll(DAYS)) {
    if (parseInt(m[1], 10) !== f.turnaroundDays) V(ch, 'TURNAROUND_MISMATCH', `'${m[0]}' not in catalog turnaround ${f.turnaroundDays ?? 'none-allowed'}`);
  }
  for (const rx of IMPERSONATION) for (const m of t.matchAll(rx)) V(ch, 'IMPERSONATION_OR_CLAIM', `'${m[0]}'`);
  for (const url of t.match(URLRX) || []) {
    let h = '';
    try { h = new URL(url).hostname.toLowerCase(); } catch (e) { /* invalid */ }
    if (!(h === 'cybermfukoni.co.ke' || h.endsWith('.cybermfukoni.co.ke') || h.endsWith('.go.ke'))) V(ch, 'DISALLOWED_LINK', url);
  }
  if (t.includes('{{') || t.includes('}}')) V(ch, 'UNFILLED_PLACEHOLDER', 'template token left in output');
}
if (b.title.length > 60) V('blog', 'TITLE_LENGTH', `${b.title.length} > 60`);
if (b.meta_description.length < 70 || b.meta_description.length > 160) V('blog', 'META_LENGTH', `${b.meta_description.length} not in [70, 160]`);
if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(b.slug)) V('blog', 'SLUG_FORMAT', b.slug);
if ((f.blogSlugs || []).includes(b.slug)) V('blog', 'SLUG_COLLISION', b.slug);
const words = (b.body_markdown.match(/\w+/g) || []).length;
if (words < 600) V('blog', 'BODY_TOO_SHORT', `${words} < 600 words`);
const card = [['faqs', b.faqs.length, 3, 6, 'blog'], ['tiktok_beats', content.tiktok.beats.length, 3, 6, 'tiktok'],
  ['tiktok_on_screen_text', content.tiktok.on_screen_text.length, 3, 6, 'tiktok'],
  ['instagram_hashtags', pack.instagram_hashtags.length, 3, 8, 'instagram']];
for (const [label, n, lo, hi, ch] of card) if (n < lo || n > hi) V(ch, 'CARDINALITY', `${label}: ${n} not in [${lo}, ${hi}]`);
const xw = xWeighted(content.x.text);
if (xw > 280) V('x', 'X_LENGTH', `${xw} > 280 weighted chars`);
if (content.instagram.caption.length > 2200) V('instagram', 'IG_CAPTION_LENGTH', '> 2200');

return [{ json: { passed: violations.length === 0, attempt, maxAttempts: cfg.maxAttempts, violations, content } }];

// Node: "Blocked Message" — compliance still failing after maxAttempts.
const f = $('Extract Facts').first().json;
const { violations, attempt } = $input.first().json;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = violations.slice(0, 15).map((v) => `• [${esc(v.channel)}] ${esc(v.rule)}: ${esc(v.detail).slice(0, 160)}`);
return [{
  json: {
    violations,
    text: [`<b>⛔ Blocked: ${esc(f.h1 || f.slug)}</b>`, `Compliance failed after ${attempt} attempts:`, ...lines,
      `Execution <code>${$execution.id}</code>`].join('\n').slice(0, 4096),
  },
}];

// Node: "Record Outcome" — rejected / expired / blocked runs. No cooldown is applied,
// so the service stays eligible; the log keeps the reason for audit.
// Decision path: $input is the Verify Decision item. Blocked path: $input is the Telegram response.
const store = $getWorkflowStaticData('global');
store.log = store.log || [];
const f = $('Extract Facts').first().json;
const j = $input.first().json;
const entry = { executionId: $execution.id, slug: f.slug, status: j.decision || 'blocked', at: new Date().toISOString() };
if (!j.decision) entry.violations = $('Blocked Message').first().json.violations;
store.log.push(entry);
if (store.log.length > 500) store.log = store.log.slice(-500);
return [{ json: entry }];

// Node: "Prepare Review" — receives the PASSING compliance item. Builds the Telegram preview and
// signed one-time approve/reject links to this execution's Wait node.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto.
const crypto = require('crypto');
const f = $('Extract Facts').first().json;
const { content, attempt } = $input.first().json;
const token = crypto.randomBytes(24).toString('hex');
const base = $execution.resumeUrl;          // {N8N_URL}/webhook-waiting/{executionId}
const link = (d) => `${base}?d=${d}&t=${token}`;

const esc = (s, n) => {
  const t = String(s ?? '');
  const cut = t.length > n ? t.slice(0, n - 1) + '…' : t;
  return cut.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
};
const text = [
  `<b>Review: ${esc(f.h1 || f.slug, 120)}</b>`,
  `Fee: ${f.priceAmbiguous ? 'ambiguous (not mentioned)' : f.priceKes ?? 'n/a'} | Turnaround: ${f.turnaroundDays ?? 'n/a'} days | Attempt ${attempt}`,
  `Why: ${esc((f.reasons || []).join('; ') || 'rotation', 300)}`,
  '',
  `<b>Blog</b>: ${esc(content.blog.title, 120)}`,
  `<b>X</b>: ${esc(content.x.text, 300)}`,
  `<b>Facebook</b>: ${esc(content.facebook.message, 900)}`,
  `<b>Instagram</b>: ${esc(content.instagram.caption, 600)}`,
  '',
  `Execution <code>${$execution.id}</code> · links expire in 48 h`,
].join('\n').slice(0, 4096);

return [{
  json: {
    token, text, approveUrl: link('approve'), rejectUrl: link('reject'),
    slug: f.slug, content,
  },
}];

// Node: "Verify Decision" — runs after the Wait node resumes (link click) or times out.
// Constant-time token comparison; a bad token loops back to the Wait node.
const crypto = require('crypto');
const expected = $('Prepare Review').first().json.token;
const q = ($input.first().json && $input.first().json.query) || {};
let decision = 'expired';                       // Wait timeout resumes with no query
if (q.t !== undefined || q.d !== undefined) {
  const a = Buffer.from(String(q.t || ''));
  const b = Buffer.from(expected);
  const valid = a.length === b.length && crypto.timingSafeEqual(a, b);
  decision = !valid ? 'invalid' : (q.d === 'approve' ? 'approve' : q.d === 'reject' ? 'reject' : 'invalid');
}
return [{ json: { decision } }];

// Node: "Sign Blog Payload" — HMAC-SHA256 over `${ts}.${body}` (docs/blog-ingestion-contract.md).
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto and env CM_BLOG_WEBHOOK_SECRET readable by Code nodes.
const crypto = require('crypto');
const secret = $env.CM_BLOG_WEBHOOK_SECRET;
if (!secret) throw new Error('CM_BLOG_WEBHOOK_SECRET is not set (or env access is blocked)');
const b = $('Prepare Review').first().json.content.blog;
const payload = {
  slug: b.slug, title: b.title, meta_description: b.meta_description, body_markdown: b.body_markdown,
  faqs: b.faqs, jsonld: b.jsonld, og_image: b.og_image, canonical_url: b.canonical_url,
};
const body = JSON.stringify(payload);
const ts = String(Math.floor(Date.now() / 1000));
const sig = crypto.createHmac('sha256', secret).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, signature: `sha256=${sig}`, slug: b.slug } }];

// Node: "Record Results" — end of the publish chain. Each publisher runs with
// "On Error: Continue", so its output is either the API response or { error }.
const store = $getWorkflowStaticData('global');
store.history = store.history || {};
store.log = store.log || [];
const review = $('Prepare Review').first().json;

const read = (name, pick) => {
  try {
    const item = $(name).first().json;
    if (item.error) return { status: 'failed', error: JSON.stringify(item.error).slice(0, 500) };
    return { status: 'published', ...pick(item) };
  } catch (e) {
    return { status: 'skipped' };               // node disabled or never reached
  }
};
const results = {
  blog: read('Publish Blog', (j) => ({ url: j.url || review.content.blog.canonical_url })),
  facebook: read('Publish Facebook', (j) => ({ id: j.id, url: j.id ? `https://www.facebook.com/${j.id}` : '' })),
  instagram: read('IG Publish', (j) => ({ id: j.id })),
  x: read('Publish X', (j) => ({ id: j.data && j.data.id, url: j.data ? `https://x.com/i/web/status/${j.data.id}` : '' })),
};
const ok = Object.values(results).filter((r) => r.status === 'published').length;
const attempted = Object.values(results).filter((r) => r.status !== 'skipped').length;
const status = attempted === 0 ? 'no_channels' : ok === attempted ? 'published' : ok ? 'partial' : 'failed';

if (ok > 0) store.history[review.slug] = new Date().toISOString();   // start cooldown
store.log.push({ executionId: $execution.id, slug: review.slug, status, results, at: new Date().toISOString() });
if (store.log.length > 500) store.log = store.log.slice(-500);

return [{ json: { status, slug: review.slug, results } }];
